args.content:
* { margin: 0; padding: 0; box-sizing: border-box; }
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.6;
  color: #1a1a1a;
  max-width: 720px;
  margin: 0 auto;
  padding: 2rem 1rem;
}
header { margin-bottom: 3rem; text-align: center; }
h1 { font-size: 2.5rem; margin-bottom: 0.5rem; letter-spacing: -0.02em; }
.subtitle { color: #555; font-size: 1.1rem; }
main { display: grid; gap: 2.5rem; }
section h2 { font-size: 1.3rem; margin-bottom: 0.75rem; color: #111; }
ul { list-style: disc; margin-left: 1.25rem; }
li { margin-bottom: 0.5rem; }
.note { font-size: 0.95rem; color: #666; font-style: italic; margin-top: 0.75rem; }
a { color: #2563eb; text-decoration: none; }
a:hover { text-decoration: underline; }
footer { margin-top: 3rem; padding-top: 1.5rem; border-top: 1px solid #e5e5e5; font-size: 0.85rem; color: #666; text-align: center; }
@media (max-width: 480px) { h1 { font-size: 1.9rem; } }
